BEGIN;

CREATE TABLE customer (
    "CustomerId" integer GENERATED BY DEFAULT AS IDENTITY
        (START WITH 3) PRIMARY KEY,
    "Name" varchar(100) NOT NULL,
    "Email" varchar(100) UNIQUE,
    "Phone" varchar(20),
    "Address" varchar(255)
);

CREATE TABLE product (
    "ProductID" integer GENERATED BY DEFAULT AS IDENTITY
        (START WITH 13) PRIMARY KEY,
    "ProductName" varchar(100) UNIQUE,
    "Category" varchar(50),
    "Price" numeric(10,2),
    "StockQuantity" integer NOT NULL,
    "Image" varchar(100),

    CONSTRAINT chk_product_price
        CHECK ("Price" > 0),

    CONSTRAINT chk_stock_quantity
        CHECK ("StockQuantity" >= 0)
);

CREATE TABLE orders (
    "OrderId" integer GENERATED BY DEFAULT AS IDENTITY
        (START WITH 4) PRIMARY KEY,
    "OrderDate" date,
    "OrderStatus" varchar(50) DEFAULT 'Pending',
    "TotalAmount" varchar(50),
    "Schedule" date,
    "CustomerId" integer,

    CONSTRAINT orders_ibfk_1
        FOREIGN KEY ("CustomerId")
        REFERENCES customer ("CustomerId")
);

CREATE TABLE orderitems (
    "OrderItemID" integer GENERATED BY DEFAULT AS IDENTITY
        (START WITH 5) PRIMARY KEY,
    "Quantity" integer NOT NULL,
    "SubTotal" numeric(10,2) NOT NULL,
    "OrderId" integer NOT NULL,
    "ProductID" integer NOT NULL,

    CONSTRAINT orderitems_ibfk_1
        FOREIGN KEY ("OrderId")
        REFERENCES orders ("OrderId"),

    CONSTRAINT orderitems_ibfk_2
        FOREIGN KEY ("ProductID")
        REFERENCES product ("ProductID"),

    CONSTRAINT chk_quantity
        CHECK ("Quantity" > 0),

    CONSTRAINT chk_subtotal_nonnegative
        CHECK ("SubTotal" >= 0)
);

CREATE TABLE delivery (
    "DeliveryId" integer GENERATED BY DEFAULT AS IDENTITY
        (START WITH 3) PRIMARY KEY,
    "DeliveryDate" date,
    "DeliveryStatus" varchar(50) DEFAULT 'Pending',
    "DeliveryAddress" varchar(255),
    "OrderId" integer UNIQUE,

    CONSTRAINT delivery_ibfk_1
        FOREIGN KEY ("OrderId")
        REFERENCES orders ("OrderId")
);

CREATE TABLE payment (
    paymentid integer GENERATED BY DEFAULT AS IDENTITY
        (START WITH 3) PRIMARY KEY,
    paymentmethod varchar(50) NOT NULL DEFAULT 'Cash',
    paymentdate date NOT NULL,
    amount numeric(10,2) NOT NULL,
    orderid integer NOT NULL UNIQUE,

    CONSTRAINT payment_ibfk_1
        FOREIGN KEY (orderid)
        REFERENCES orders ("OrderId"),

    CONSTRAINT chk_payment_amount
        CHECK (amount > 0)
);

CREATE INDEX idx_orders_customer
    ON orders ("CustomerId");

CREATE INDEX idx_orderitems_order
    ON orderitems ("OrderId");

CREATE INDEX idx_orderitems_product
    ON orderitems ("ProductID");

